package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.awt.geom.Point2D;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

/** Finds one legal click point per marker that minimizes the complete cyclic route. */
final class AttainableRouteOptimizer
{
    private static final int ITERATIONS = 6000;
    private static final double BETA_ONE = 0.9;
    private static final double BETA_TWO = 0.999;
    private static final double ADAM_EPSILON = 1e-8;

    static final class Result
    {
        final double travel;
        final List<Point2D.Double> points;

        Result(double travel, List<Point2D.Double> points)
        {
            this.travel = travel;
            this.points = points;
        }
    }

    private AttainableRouteOptimizer() {}

    static Result solve(Rectangle[] markers)
    {
        if (!valid(markers))
        {
            return new Result(Double.NaN, Collections.emptyList());
        }

        Rectangle common = new Rectangle(markers[0]);
        for (int i = 1; i < markers.length; i++)
        {
            common = common.intersection(markers[i]);
        }
        if (!common.isEmpty())
        {
            List<Point2D.Double> shared = new ArrayList<>(markers.length);
            Point2D.Double point = new Point2D.Double(common.getCenterX(), common.getCenterY());
            for (int i = 0; i < markers.length; i++)
            {
                shared.add(new Point2D.Double(point.x, point.y));
            }
            return new Result(0, Collections.unmodifiableList(shared));
        }

        int count = markers.length;
        double[] x = new double[count];
        double[] y = new double[count];
        double[] firstMomentX = new double[count];
        double[] firstMomentY = new double[count];
        double[] secondMomentX = new double[count];
        double[] secondMomentY = new double[count];
        double[] bestX = new double[count];
        double[] bestY = new double[count];
        double scale = 1;
        for (int i = 0; i < count; i++)
        {
            Rectangle marker = markers[i];
            x[i] = marker.getCenterX();
            y[i] = marker.getCenterY();
            scale = Math.max(scale, Math.hypot(marker.x + marker.width, marker.y + marker.height));
        }

        double bestTravel = travel(x, y);
        double checkpointTravel = bestTravel;
        int stagnantCheckpoints = 0;
        System.arraycopy(x, 0, bestX, 0, count);
        System.arraycopy(y, 0, bestY, 0, count);
        double baseStep = Math.max(2.0, scale * 0.018);

        for (int iteration = 1; iteration <= ITERATIONS; iteration++)
        {
            double step = baseStep / (1.0 + iteration / 350.0);
            for (int i = 0; i < count; i++)
            {
                int previous = (i + count - 1) % count;
                int next = (i + 1) % count;
                double gradientX = unitX(x[i], y[i], x[previous], y[previous])
                    + unitX(x[i], y[i], x[next], y[next]);
                double gradientY = unitY(x[i], y[i], x[previous], y[previous])
                    + unitY(x[i], y[i], x[next], y[next]);

                firstMomentX[i] = BETA_ONE * firstMomentX[i] + (1 - BETA_ONE) * gradientX;
                firstMomentY[i] = BETA_ONE * firstMomentY[i] + (1 - BETA_ONE) * gradientY;
                secondMomentX[i] = BETA_TWO * secondMomentX[i] + (1 - BETA_TWO) * gradientX * gradientX;
                secondMomentY[i] = BETA_TWO * secondMomentY[i] + (1 - BETA_TWO) * gradientY * gradientY;

                double firstCorrection = 1 - Math.pow(BETA_ONE, iteration);
                double secondCorrection = 1 - Math.pow(BETA_TWO, iteration);
                double adjustedX = firstMomentX[i] / firstCorrection;
                double adjustedY = firstMomentY[i] / firstCorrection;
                double varianceX = secondMomentX[i] / secondCorrection;
                double varianceY = secondMomentY[i] / secondCorrection;
                Rectangle marker = markers[i];
                x[i] = clamp(x[i] - step * adjustedX / (Math.sqrt(varianceX) + ADAM_EPSILON),
                    marker.getMinX(), marker.getMaxX());
                y[i] = clamp(y[i] - step * adjustedY / (Math.sqrt(varianceY) + ADAM_EPSILON),
                    marker.getMinY(), marker.getMaxY());
            }

            double candidateTravel = travel(x, y);
            if (candidateTravel < bestTravel)
            {
                bestTravel = candidateTravel;
                System.arraycopy(x, 0, bestX, 0, count);
                System.arraycopy(y, 0, bestY, 0, count);
            }
            if (iteration % 50 == 0)
            {
                if (checkpointTravel - bestTravel < 1e-5)
                {
                    stagnantCheckpoints++;
                    if (stagnantCheckpoints >= 10) break;
                }
                else
                {
                    stagnantCheckpoints = 0;
                }
                checkpointTravel = bestTravel;
            }
        }

        List<Point2D.Double> points = new ArrayList<>(count);
        for (int i = 0; i < count; i++)
        {
            points.add(new Point2D.Double(bestX[i], bestY[i]));
        }
        return new Result(bestTravel, Collections.unmodifiableList(points));
    }

    private static boolean valid(Rectangle[] markers)
    {
        if (markers == null || markers.length == 0) return false;
        for (Rectangle marker : markers)
        {
            if (marker == null || marker.width < 0 || marker.height < 0) return false;
        }
        return true;
    }

    private static double travel(double[] x, double[] y)
    {
        double total = 0;
        for (int i = 0; i < x.length; i++)
        {
            int next = (i + 1) % x.length;
            total += Math.hypot(x[next] - x[i], y[next] - y[i]);
        }
        return total;
    }

    private static double unitX(double x, double y, double otherX, double otherY)
    {
        double distance = Math.hypot(x - otherX, y - otherY);
        return distance < 1e-9 ? 0 : (x - otherX) / distance;
    }

    private static double unitY(double x, double y, double otherX, double otherY)
    {
        double distance = Math.hypot(x - otherX, y - otherY);
        return distance < 1e-9 ? 0 : (y - otherY) / distance;
    }

    private static double clamp(double value, double minimum, double maximum)
    {
        return Math.max(minimum, Math.min(maximum, value));
    }
}

package com.mvpitsolutions.rooftopcamera;

final class AutomaticCameraShiftDetector
{
    private static final int MANUAL_SETTLE_TICKS = 25;
    private boolean initialized;
    private int baselineYaw;
    private int baselinePitch;
    private int baselineZoom;
    private int manualSettleTicks;

    boolean observe(int yaw, int pitch, int zoom, boolean manualInput, boolean calibrationLapActive)
    {
        if (!initialized || !calibrationLapActive)
        {
            setBaseline(yaw, pitch, zoom);
            manualSettleTicks = manualInput ? MANUAL_SETTLE_TICKS : 0;
            return false;
        }
        if (manualInput)
        {
            manualSettleTicks = MANUAL_SETTLE_TICKS;
        }
        if (manualSettleTicks > 0)
        {
            manualSettleTicks--;
            setBaseline(yaw, pitch, zoom);
            return false;
        }

        boolean shifted = Math.abs(RooftopCameraPlugin.signedYawDelta(baselineYaw, yaw)) > 16
            || Math.abs(pitch - baselinePitch) > 8
            || Math.abs(zoom - baselineZoom) > 16;
        if (shifted)
        {
            setBaseline(yaw, pitch, zoom);
        }
        return shifted;
    }

    void reset()
    {
        initialized = false;
        manualSettleTicks = 0;
    }

    private void setBaseline(int yaw, int pitch, int zoom)
    {
        initialized = true;
        baselineYaw = yaw;
        baselinePitch = pitch;
        baselineZoom = zoom;
    }
}

package com.mvpitsolutions.rooftopcamera;

final class CameraBounds
{
    private int minPitch;
    private int maxPitch;
    private int minZoom;
    private int maxZoom;

    CameraBounds()
    {
        this(128, 2040, -400, 1004);
    }

    CameraBounds(int minPitch, int maxPitch, int minZoom, int maxZoom)
    {
        this.minPitch = minPitch;
        this.maxPitch = maxPitch;
        this.minZoom = minZoom;
        this.maxZoom = maxZoom;
    }

    int clampPitch(int value) { return clamp(value, minPitch, maxPitch); }
    int clampZoom(int value) { return clamp(value, minZoom, maxZoom); }

    boolean learnPitchLimit(int target, int actual)
    {
        if (target < actual && actual > minPitch)
        {
            minPitch = actual;
            return true;
        }
        if (target > actual && actual < maxPitch)
        {
            maxPitch = actual;
            return true;
        }
        return false;
    }

    boolean learnZoomLimit(int target, int actual)
    {
        if (target < actual && actual > minZoom)
        {
            minZoom = actual;
            return true;
        }
        if (target > actual && actual < maxZoom)
        {
            maxZoom = actual;
            return true;
        }
        return false;
    }

    String serialize()
    {
        return minPitch + "," + maxPitch + "," + minZoom + "," + maxZoom;
    }

    static CameraBounds parse(String value)
    {
        if (value == null || value.isEmpty()) return new CameraBounds();
        try
        {
            String[] parts = value.split(",");
            if (parts.length != 4) return new CameraBounds();
            int minPitch = Integer.parseInt(parts[0]);
            int maxPitch = Integer.parseInt(parts[1]);
            int minZoom = Integer.parseInt(parts[2]);
            int maxZoom = Integer.parseInt(parts[3]);
            if (minPitch >= maxPitch || minZoom >= maxZoom)
            {
                return new CameraBounds();
            }
            return new CameraBounds(minPitch, maxPitch, minZoom, maxZoom);
        }
        catch (RuntimeException ignored)
        {
            return new CameraBounds();
        }
    }

    private static int clamp(int value, int min, int max)
    {
        return Math.max(min, Math.min(max, value));
    }
}

package com.mvpitsolutions.rooftopcamera;

final class CameraCandidateStats
{
    final int yaw;
    final int pitch;
    final int zoom;
    int samples;
    int rejections;
    double overlapTotal;
    double overlapAreaTotal;
    double gapTotal;
    double centerTotal;
    double mouseTotal;
    ScreenMarkerLayout representativeLayout;
    private double representativeCost = Double.POSITIVE_INFINITY;
    private ScreenMarkerLayout cachedAttainableLayout;
    private double cachedAttainableTravel = Double.POSITIVE_INFINITY;

    CameraCandidateStats(int yaw, int pitch, int zoom)
    {
        this.yaw = yaw;
        this.pitch = pitch;
        this.zoom = zoom;
    }

    void add(LapOptimizer.CompletedLap lap, ScreenMarkerLayout layout)
    {
        samples++;
        overlapTotal += lap.overlappingTransitions;
        overlapAreaTotal += lap.overlapArea;
        gapTotal += lap.markerGap;
        centerTotal += lap.markerTravel;
        mouseTotal += lap.mouseTravel;
        double cost = lap.attainableTravel * 1_000_000d
            - lap.overlappingTransitions * 1_000d - lap.overlapArea;
        if (layout != null && cost < representativeCost)
        {
            representativeCost = cost;
            representativeLayout = layout;
        }
    }

    double averageOverlap() { return samples == 0 ? 0 : overlapTotal / samples; }
    double averageOverlapArea() { return samples == 0 ? 0 : overlapAreaTotal / samples; }
    double averageGap() { return samples == 0 ? Double.POSITIVE_INFINITY : gapTotal / samples; }
    double averageCenter() { return samples == 0 ? Double.POSITIVE_INFINITY : centerTotal / samples; }
    double averageMouse() { return samples == 0 ? Double.POSITIVE_INFINITY : mouseTotal / samples; }
    boolean isEligible() { return samples >= 1; }
    boolean isRejected() { return samples == 0 && rejections >= 2; }
    void reject() { rejections++; }
    void rejectAsUnreachable() { rejections = Math.max(rejections, 2); }

    boolean isBetterThan(CameraCandidateStats other)
    {
        if (other == null) return true;
        int overlap = Double.compare(averageOverlap(), other.averageOverlap());
        if (overlap != 0) return overlap > 0;
        int overlapArea = Double.compare(averageOverlapArea(), other.averageOverlapArea());
        if (overlapArea != 0) return overlapArea > 0;
        int gap = Double.compare(averageGap(), other.averageGap());
        if (gap != 0) return gap < 0;
        double thisAttainable = representativeAttainableTravel();
        double otherAttainable = other.representativeAttainableTravel();
        int attainable = Double.compare(thisAttainable, otherAttainable);
        if (attainable != 0 && (Double.isFinite(thisAttainable) || Double.isFinite(otherAttainable)))
        {
            return attainable < 0;
        }
        int center = Double.compare(averageCenter(), other.averageCenter());
        if (center != 0) return center < 0;
        return false;
    }

    double representativeAttainableTravel()
    {
        if (representativeLayout == null) return Double.POSITIVE_INFINITY;
        if (representativeLayout != cachedAttainableLayout)
        {
            cachedAttainableLayout = representativeLayout;
            cachedAttainableTravel = AttainableRouteOptimizer.solve(
                representativeLayout.markers.toArray(new java.awt.Rectangle[0])).travel;
        }
        return cachedAttainableTravel;
    }

    boolean isOperational()
    {
        if (representativeLayout == null || !representativeLayout.verifiedInnerRectangles
            || !representativeLayout.releaseValidated
            || representativeLayout.markers.isEmpty()) return false;
        for (java.awt.Rectangle marker : representativeLayout.markers)
        {
            if (marker == null || marker.width < 8 || marker.height < 8) return false;
        }
        return true;
    }
}

package com.mvpitsolutions.rooftopcamera;

final class CameraGuidanceState
{
    final int yawDelta;
    final int pitchDelta;
    final int zoomDelta;
    final boolean calibration;
    final int completedLaps;
    final int targetLaps;

    CameraGuidanceState(int yawDelta, int pitchDelta, int zoomDelta,
        boolean calibration, int completedLaps)
    {
        this(yawDelta, pitchDelta, zoomDelta, calibration, completedLaps,
            CameraSearchPlanner.INITIAL_VALID_LAPS);
    }

    CameraGuidanceState(int yawDelta, int pitchDelta, int zoomDelta,
        boolean calibration, int completedLaps, int targetLaps)
    {
        this.yawDelta = yawDelta;
        this.pitchDelta = pitchDelta;
        this.zoomDelta = zoomDelta;
        this.calibration = calibration;
        this.completedLaps = completedLaps;
        this.targetLaps = Math.max(1, targetLaps);
    }

    boolean isYawAligned() { return Math.abs(yawDelta) <= 8; }
    boolean isPitchAligned() { return Math.abs(pitchDelta) <= 4; }
    boolean isZoomAligned() { return Math.abs(zoomDelta) <= 8; }
    boolean isAligned() { return isYawAligned() && isPitchAligned() && isZoomAligned(); }

    String turnLabel()
    {
        return isYawAligned() ? "YAW SET" : yawDelta > 0 ? "TURN RIGHT" : "TURN LEFT";
    }

    String tiltLabel()
    {
        return isPitchAligned() ? "PITCH SET" : pitchDelta > 0 ? "TILT UP" : "TILT DOWN";
    }

    String zoomLabel()
    {
        return isZoomAligned() ? "ZOOM SET" : zoomDelta > 0 ? "ZOOM IN" : "ZOOM OUT";
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Graphics2D;
import java.awt.Point;
import java.awt.Rectangle;
import java.awt.RenderingHints;
import net.runelite.client.ui.overlay.components.LayoutableRenderableEntity;

final class CameraRadarComponent implements LayoutableRenderableEntity
{
    private static final Color SURFACE = new Color(20, 31, 41, 245);
    private static final Color SURFACE_EDGE = new Color(69, 96, 113, 210);
    private static final Color MUTED = new Color(151, 170, 182);
    private static final Color GRID = new Color(83, 111, 126, 125);
    private static final Color AQUA = new Color(68, 224, 196);
    private static final Color GOLD = new Color(255, 194, 68);
    private static final Color TRACK = new Color(46, 64, 76);

    private final Rectangle bounds = new Rectangle();
    private Point preferredLocation = new Point();
    private Dimension preferredSize = new Dimension(344, 260);
    private CameraGuidanceState state;
    private String courseName = "Rooftop course";
    private int nextObstacle = -1;
    private int routeProgress;
    private int routeTotal;
    private boolean stableLap = true;
    private double bestOverlap = Double.NaN;
    private double bestGap = Double.NaN;
    private int evidenceLaps;
    private int testedViews;
    private double lastTravel = Double.NaN;
    private String calibrationNote;

    void setState(CameraGuidanceState state)
    {
        this.state = state;
    }

    void setCalibrationNote(String calibrationNote)
    {
        this.calibrationNote = calibrationNote;
    }

    void setRouteState(String courseName, int nextObstacle, int routeProgress,
        int routeTotal, boolean stableLap)
    {
        this.courseName = courseName;
        this.nextObstacle = nextObstacle;
        this.routeProgress = routeProgress;
        this.routeTotal = routeTotal;
        this.stableLap = stableLap;
    }

    void setHistoryState(TravelProfile profile, double lastTravel)
    {
        setHistoryState(profile, lastTravel, profile == null ? 0 : 1);
    }

    void setHistoryState(TravelProfile profile, double lastTravel, int testedViews)
    {
        bestOverlap = profile == null ? Double.NaN : profile.overlappingTransitions;
        bestGap = profile == null ? Double.NaN : profile.markerGap;
        evidenceLaps = profile == null ? 0 : profile.samples;
        this.testedViews = testedViews;
        this.lastTravel = lastTravel;
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        if (state == null) return null;

        int x = preferredLocation.x;
        int y = preferredLocation.y;
        int width = Math.max(320, preferredSize.width);
        int height = 260;
        bounds.setBounds(x, y, width, height);

        Graphics2D g = (Graphics2D) graphics.create();
        g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);
        g.setColor(SURFACE);
        g.fillRoundRect(x, y, width, height, 8, 8);
        g.setColor(SURFACE_EDGE);
        g.drawRoundRect(x, y, width - 1, height - 1, 8, 8);

        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 15));
        g.setColor(Color.WHITE);
        g.drawString(courseName.toUpperCase(), x + 14, y + 23);
        String nextLabel = nextObstacle < 0 ? "ACQUIRING" : "NEXT  " + nextObstacle;
        int nextWidth = g.getFontMetrics().stringWidth(nextLabel);
        g.setColor(GOLD);
        g.drawString(nextLabel, x + width - nextWidth - 14, y + 23);

        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        g.setColor(state.isAligned() ? AQUA : Color.WHITE);
        String cameraStatus = state.isAligned() ? "CAMERA LOCKED"
            : state.calibration ? "ALIGN CAMERA" : "ALIGN WINNING CAMERA";
        if (!stableLap) cameraStatus = "CAMERA CHANGED - NEXT LAP COUNTS";
        if (calibrationNote != null) cameraStatus = calibrationNote;
        if (calibrationNote != null) g.setColor(GOLD);
        g.setFont(new Font(Font.SANS_SERIF, Font.PLAIN, 11));
        g.setColor(MUTED);
        String lapLabel = "LAP  " + routeProgress + " / " + routeTotal;
        int lapWidth = g.getFontMetrics().stringWidth(lapLabel);
        g.drawString(lapLabel, x + width - lapWidth - 14, y + 44);

        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        if (calibrationNote != null) g.setColor(GOLD);
        else g.setColor(state.isAligned() ? AQUA : Color.WHITE);
        int statusWidth = Math.max(0, width - lapWidth - 42);
        g.drawString(ellipsize(g, cameraStatus, statusWidth), x + 14, y + 44);

        drawRadar(g, x + 76, y + 104, 43);
        drawZoom(g, x + 143, y + 67, 16, 76);
        drawReadout(g, x + 181, y + 78);
        drawRouteProgress(g, x + 14, y + 161, width - 28);
        drawCalibrationProgress(g, x + 14, y + 191, width - 28);
        drawHistory(g, x + 14, y + 218, width - 28);
        g.dispose();
        return new Dimension(width, height);
    }

    private static String ellipsize(Graphics2D graphics, String text, int maxWidth)
    {
        if (graphics.getFontMetrics().stringWidth(text) <= maxWidth) return text;
        String suffix = "...";
        int end = text.length();
        while (end > 0 && graphics.getFontMetrics().stringWidth(text.substring(0, end) + suffix) > maxWidth)
        {
            end--;
        }
        return end == 0 ? suffix : text.substring(0, end).trim() + suffix;
    }

    private void drawRadar(Graphics2D g, int centerX, int centerY, int radius)
    {
        g.setStroke(new BasicStroke(1f));
        g.setColor(GRID);
        g.drawOval(centerX - radius, centerY - radius, radius * 2, radius * 2);
        g.drawOval(centerX - radius / 2, centerY - radius / 2, radius, radius);
        g.drawLine(centerX - radius, centerY, centerX + radius, centerY);
        g.drawLine(centerX, centerY - radius, centerX, centerY + radius);

        int targetX = centerX + scale(state.yawDelta, 512, radius - 4);
        int targetY = centerY - scale(state.pitchDelta, 256, radius - 4);
        g.setStroke(new BasicStroke(2f));
        g.setColor(state.isAligned() ? AQUA : GOLD);
        g.drawLine(centerX, centerY, targetX, targetY);
        g.fillOval(targetX - 5, targetY - 5, 10, 10);
        g.setColor(AQUA);
        g.fillOval(centerX - 3, centerY - 3, 6, 6);

        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        g.setColor(MUTED);
        g.drawString("L", centerX - radius - 9, centerY + 3);
        g.drawString("R", centerX + radius + 4, centerY + 3);
        g.drawString("UP", centerX - 6, centerY - radius - 5);
        g.drawString("DN", centerX - 6, centerY + radius + 11);
    }

    private void drawZoom(Graphics2D g, int x, int y, int width, int height)
    {
        g.setColor(TRACK);
        g.fillRoundRect(x, y, width, height, width, width);
        int markerY = y + (height / 2) - scale(state.zoomDelta, 512, (height / 2) - 5);
        g.setColor(state.isZoomAligned() ? AQUA : GOLD);
        g.fillRoundRect(x - 3, markerY - 3, width + 6, 6, 6, 6);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        g.setColor(MUTED);
        g.drawString("IN", x - 1, y - 5);
        g.drawString("OUT", x - 3, y + height + 11);
    }

    private void drawReadout(Graphics2D g, int x, int y)
    {
        drawStatus(g, x, y, state.turnLabel(), state.isYawAligned());
        drawStatus(g, x, y + 22, state.tiltLabel(), state.isPitchAligned());
        drawStatus(g, x, y + 44, state.zoomLabel(), state.isZoomAligned());
    }

    private void drawStatus(Graphics2D g, int x, int y, String label, boolean complete)
    {
        g.setColor(complete ? AQUA : GOLD);
        g.fillOval(x, y - 7, 7, 7);
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 12));
        g.drawString(label, x + 13, y);
    }

    private void drawRouteProgress(Graphics2D g, int x, int y, int width)
    {
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        g.setColor(MUTED);
        g.drawString("ROUTE", x, y);
        int barY = y + 6;
        g.setColor(TRACK);
        g.fillRoundRect(x, barY, width, 6, 6, 6);
        int filled = routeTotal <= 0 ? 0 : (int) Math.round(width
            * Math.min(routeProgress, routeTotal) / (double) routeTotal);
        if (filled > 0)
        {
            g.setColor(AQUA);
            g.fillRoundRect(x, barY, filled, 6, 6, 6);
        }
    }

    private void drawCalibrationProgress(Graphics2D g, int x, int y, int width)
    {
        g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 10));
        g.setColor(MUTED);
        String label = state.calibration
            ? "CALIBRATION  " + Math.min(state.completedLaps, state.targetLaps)
                + " / " + state.targetLaps
            : "CALIBRATION COMPLETE";
        g.drawString(label, x, y);
        int gap = 3;
        int segmentWidth = (width - (state.targetLaps - 1) * gap) / state.targetLaps;
        for (int i = 0; i < state.targetLaps; i++)
        {
            g.setColor(!state.calibration || i < state.completedLaps ? AQUA : TRACK);
            g.fillRoundRect(x + i * (segmentWidth + gap), y + 6, segmentWidth, 7, 4, 4);
        }
    }

    private void drawHistory(Graphics2D g, int x, int y, int width)
    {
        g.setColor(SURFACE_EDGE);
        g.drawLine(x, y, x + width, y);
        String[] labels = {"BEST OBSERVED", "MARKER GAP", "TESTED VIEWS", "LAST LAP"};
        String[] values = {
            Double.isNaN(bestOverlap) ? "--" : String.format("%.1f / %d", bestOverlap, routeTotal),
            Double.isNaN(bestGap) ? "--" : String.format("%.0f px", bestGap),
            testedViews == 0 ? "--" : testedViews + " views",
            Double.isNaN(lastTravel) ? "--" : String.format("%.0f px", lastTravel)
        };
        int columnWidth = width / labels.length;
        for (int i = 0; i < labels.length; i++)
        {
            int center = x + i * columnWidth + columnWidth / 2;
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 8));
            g.setColor(MUTED);
            drawCentered(g, labels[i], center, y + 13);
            g.setFont(new Font(Font.SANS_SERIF, Font.BOLD, 11));
            g.setColor(i == 0 ? AQUA : Color.WHITE);
            drawCentered(g, values[i], center, y + 29);
        }
    }

    private static void drawCentered(Graphics2D g, String text, int centerX, int baseline)
    {
        g.drawString(text, centerX - g.getFontMetrics().stringWidth(text) / 2, baseline);
    }

    private static int scale(int value, int range, int output)
    {
        double normalized = Math.max(-1d, Math.min(1d, value / (double) range));
        return (int) Math.round(normalized * output);
    }

    @Override
    public Rectangle getBounds() { return bounds; }

    @Override
    public void setPreferredLocation(Point preferredLocation)
    {
        this.preferredLocation = preferredLocation;
    }

    @Override
    public void setPreferredSize(Dimension preferredSize)
    {
        this.preferredSize = preferredSize;
    }
}

package com.mvpitsolutions.rooftopcamera;

final class CameraReachabilityTracker
{
    private static final int INPUTS_AT_UNCHANGED_LIMIT = 5;
    private static final int DRAGS_AT_UNREACHABLE_YAW = 12;
    private CameraTarget target;
    private int lastYaw;
    private int lastPitch;
    private int lastZoom;
    private int unchangedYawInputs;
    private int unchangedPitchInputs;
    private int unchangedZoomInputs;
    private boolean yawInputPending;
    private boolean pitchInputPending;
    private boolean zoomInputPending;
    private boolean targetUnreachable;

    synchronized boolean observe(CameraTarget newTarget, int pitch, int zoom, CameraBounds bounds)
    {
        return observe(newTarget, newTarget == null ? 0 : newTarget.yaw, pitch, zoom, bounds);
    }

    synchronized boolean observe(CameraTarget newTarget, int yaw, int pitch, int zoom, CameraBounds bounds)
    {
        boolean changed = false;
        if (newTarget == null || target == null || !newTarget.key().equals(target.key()))
        {
            target = newTarget;
            unchangedYawInputs = 0;
            unchangedPitchInputs = 0;
            unchangedZoomInputs = 0;
            yawInputPending = false;
            pitchInputPending = false;
            zoomInputPending = false;
            targetUnreachable = false;
        }
        if (yaw != lastYaw)
        {
            unchangedYawInputs = 0;
        }
        else if (yawInputPending && target != null
            && Math.abs(RooftopCameraPlugin.signedYawDelta(yaw, target.yaw)) > 8
            && ++unchangedYawInputs >= DRAGS_AT_UNREACHABLE_YAW)
        {
            targetUnreachable = true;
            unchangedYawInputs = 0;
        }
        if (pitch != lastPitch)
        {
            unchangedPitchInputs = 0;
        }
        else if (pitchInputPending && target != null && Math.abs(target.pitch - pitch) > 4
            && ++unchangedPitchInputs >= INPUTS_AT_UNCHANGED_LIMIT)
        {
            changed |= bounds.learnPitchLimit(target.pitch, pitch);
            unchangedPitchInputs = 0;
        }
        if (zoom != lastZoom)
        {
            unchangedZoomInputs = 0;
        }
        else if (zoomInputPending && target != null && Math.abs(target.zoom - zoom) > 8
            && ++unchangedZoomInputs >= INPUTS_AT_UNCHANGED_LIMIT)
        {
            changed |= bounds.learnZoomLimit(target.zoom, zoom);
            unchangedZoomInputs = 0;
        }
        lastYaw = yaw;
        lastPitch = pitch;
        lastZoom = zoom;
        yawInputPending = false;
        pitchInputPending = false;
        zoomInputPending = false;
        return changed;
    }

    synchronized void cameraDrag(int yaw)
    {
        if (target == null)
        {
            return;
        }
        if (Math.abs(RooftopCameraPlugin.signedYawDelta(yaw, target.yaw)) > 8)
        {
            yawInputPending = true;
        }
        else
        {
            unchangedYawInputs = 0;
        }
        if (Math.abs(RooftopCameraPlugin.signedYawDelta(yaw, target.yaw)) > 8
            || Math.abs(target.pitch - lastPitch) <= 4)
        {
            unchangedPitchInputs = 0;
            return;
        }
        pitchInputPending = true;
    }

    synchronized boolean consumeTargetUnreachable()
    {
        boolean result = targetUnreachable;
        targetUnreachable = false;
        return result;
    }

    synchronized void zoomInput(int wheelRotation)
    {
        if (target == null || Math.abs(target.zoom - lastZoom) <= 8)
        {
            unchangedZoomInputs = 0;
            return;
        }
        boolean towardTarget = target.zoom < lastZoom ? wheelRotation > 0 : wheelRotation < 0;
        if (!towardTarget)
        {
            return;
        }
        zoomInputPending = true;
    }

    synchronized void reset()
    {
        target = null;
        unchangedYawInputs = 0;
        unchangedPitchInputs = 0;
        unchangedZoomInputs = 0;
        yawInputPending = false;
        pitchInputPending = false;
        zoomInputPending = false;
        targetUnreachable = false;
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.util.ArrayList;
import java.util.List;

final class CameraSearchPlanner
{
    static final int INITIAL_VALID_LAPS = 6;
    static final int MAX_VALID_LAPS = INITIAL_VALID_LAPS;
    private static final int WIDE_EXPLORATION_SAMPLES = 6;
    // Start with small, route-safe probes. A mechanically valid camera extreme can
    // make every obstacle disappear, which is useless for the low-mouse-travel goal.
    private static final int PITCH_PROBE_DELTA = 128;
    private static final int ZOOM_PROBE_DELTA = 64;
    private final CompoundViewPredictor compoundPredictor = new CompoundViewPredictor();

    CameraTarget nextTarget(SearchHistory history, CameraCandidateStats ignoredBest,
        CameraTarget current, CameraBounds bounds)
    {
        return nextTarget(history, ignoredBest, current, bounds, INITIAL_VALID_LAPS);
    }

    CameraTarget nextTarget(SearchHistory history, CameraCandidateStats ignoredBest,
        CameraTarget current, CameraBounds bounds, int targetSamples)
    {
        if (history.totalSamples() >= targetSamples)
        {
            return null;
        }
        CameraCandidateStats anchor = history.first();
        if (anchor == null)
        {
            return canonicalize(current);
        }

        int explorationSamples = Math.min(WIDE_EXPLORATION_SAMPLES, targetSamples);
        if (history.totalSamples() < explorationSamples)
        {
            for (CameraTarget target : explorationTargets(anchor, bounds))
            {
                if (needsLap(history, target)) return target;
            }
        }

        CompoundViewPredictor.Prediction prediction = compoundPredictor.bestPrediction(history, bounds);
        if (prediction != null && needsLap(history, prediction.target))
        {
            return prediction.target;
        }

        CameraCandidateStats measuredBest = history.best();
        if (measuredBest != null)
        {
            CameraTarget measuredCenter = new CameraTarget(
                measuredBest.yaw, measuredBest.pitch, measuredBest.zoom);
            for (CameraTarget target : precisionTargets(measuredCenter, bounds))
            {
                if (needsLap(history, target)) return target;
            }
        }

        if (history.totalSamples() == targetSamples - 1)
        {
            CameraCandidateStats winner = history.best();
            return winner == null ? null : new CameraTarget(winner.yaw, winner.pitch, winner.zoom);
        }

        if (history.totalSamples() < targetSamples)
        {
            CameraCandidateStats winner = history.best();
            return winner == null ? null : new CameraTarget(winner.yaw, winner.pitch, winner.zoom);
        }
        return null;
    }

    boolean isComplete(SearchHistory history)
    {
        return isComplete(history, INITIAL_VALID_LAPS);
    }

    boolean isComplete(SearchHistory history, int targetSamples)
    {
        return history.totalSamples() >= targetSamples;
    }

    private static boolean needsLap(SearchHistory history, CameraTarget target)
    {
        CameraCandidateStats candidate = history.get(target);
        return candidate == null || (candidate.samples == 0 && !candidate.isRejected());
    }

    private static List<CameraTarget> explorationTargets(CameraCandidateStats anchor, CameraBounds bounds)
    {
        List<CameraTarget> targets = new ArrayList<>();
        int lowPitch = ceilToStep(bounds.clampPitch(anchor.pitch - PITCH_PROBE_DELTA), 8);
        int highPitch = floorToStep(bounds.clampPitch(anchor.pitch + PITCH_PROBE_DELTA), 8);
        int lowZoom = ceilToStep(bounds.clampZoom(anchor.zoom - ZOOM_PROBE_DELTA), 16);
        int highZoom = floorToStep(bounds.clampZoom(anchor.zoom + ZOOM_PROBE_DELTA), 16);
        addUnique(targets, new CameraTarget(anchor.yaw, anchor.pitch, anchor.zoom));
        // Establish the usable tilt/zoom envelope before spending experiments on yaw.
        addUnique(targets, new CameraTarget(anchor.yaw, lowPitch, anchor.zoom));
        addUnique(targets, new CameraTarget(anchor.yaw, highPitch, anchor.zoom));
        addUnique(targets, new CameraTarget(anchor.yaw, anchor.pitch, lowZoom));
        addUnique(targets, new CameraTarget(anchor.yaw, anchor.pitch, highZoom));
        addUnique(targets, new CameraTarget(normalizeYaw(anchor.yaw + 683), anchor.pitch, anchor.zoom));
        addUnique(targets, new CameraTarget(normalizeYaw(anchor.yaw + 1365), anchor.pitch, anchor.zoom));
        return targets;
    }

    private static List<CameraTarget> precisionTargets(CameraTarget center, CameraBounds bounds)
    {
        List<CameraTarget> targets = new ArrayList<>();
        addUnique(targets, new CameraTarget(normalizeYaw(center.yaw - 128), center.pitch, center.zoom));
        addUnique(targets, new CameraTarget(normalizeYaw(center.yaw + 128), center.pitch, center.zoom));
        addUnique(targets, new CameraTarget(normalizeYaw(center.yaw - 64), center.pitch, center.zoom));
        addUnique(targets, new CameraTarget(normalizeYaw(center.yaw + 64), center.pitch, center.zoom));
        addUnique(targets, new CameraTarget(center.yaw, bounds.clampPitch(center.pitch - 64), center.zoom));
        addUnique(targets, new CameraTarget(center.yaw, bounds.clampPitch(center.pitch + 64), center.zoom));
        addUnique(targets, new CameraTarget(center.yaw, center.pitch, bounds.clampZoom(center.zoom - 64)));
        addUnique(targets, new CameraTarget(center.yaw, center.pitch, bounds.clampZoom(center.zoom + 64)));
        targets.removeIf(target -> target.key().equals(center.key()));
        return targets;
    }

    private static CameraCandidateStats bestOf(SearchHistory history, List<CameraTarget> targets)
    {
        CameraCandidateStats best = null;
        for (CameraTarget target : targets)
        {
            CameraCandidateStats candidate = history.get(target);
            if (candidate != null && candidate.isEligible() && candidate.isBetterThan(best)) best = candidate;
        }
        return best;
    }

    private static void addUnique(List<CameraTarget> targets, CameraTarget target)
    {
        CameraTarget canonical = canonicalize(target);
        if (targets.stream().noneMatch(existing -> existing.key().equals(canonical.key())))
        {
            targets.add(canonical);
        }
    }

    private static CameraTarget canonicalize(CameraTarget target)
    {
        return new CameraTarget(normalizeYaw(quantize(target.yaw, 16)),
            quantize(target.pitch, 8), quantize(target.zoom, 16));
    }

    private static int quantize(int value, int step)
    {
        return Math.round((float) value / step) * step;
    }

    private static int floorToStep(int value, int step)
    {
        return Math.floorDiv(value, step) * step;
    }

    private static int ceilToStep(int value, int step)
    {
        return -Math.floorDiv(-value, step) * step;
    }

    static int normalizeYaw(int yaw) { return ((yaw % 2048) + 2048) % 2048; }
}

package com.mvpitsolutions.rooftopcamera;

final class CameraSettleTracker
{
    private static final int REQUIRED_STABLE_TICKS = 3;
    private boolean pending;
    private int stableTicks;
    private int yaw;
    private int pitch;
    private int zoom;

    void begin(int yaw, int pitch, int zoom)
    {
        pending = true;
        stableTicks = 0;
        this.yaw = yaw;
        this.pitch = pitch;
        this.zoom = zoom;
    }

    boolean observe(int yaw, int pitch, int zoom)
    {
        if (!pending) return false;
        boolean stable = Math.abs(RooftopCameraPlugin.signedYawDelta(this.yaw, yaw)) <= 2
            && Math.abs(this.pitch - pitch) <= 2 && Math.abs(this.zoom - zoom) <= 2;
        stableTicks = stable ? stableTicks + 1 : 0;
        this.yaw = yaw;
        this.pitch = pitch;
        this.zoom = zoom;
        if (stableTicks < REQUIRED_STABLE_TICKS) return false;
        pending = false;
        return true;
    }

    boolean isPending() { return pending; }

    void reset()
    {
        pending = false;
        stableTicks = 0;
    }
}

