package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.awt.Shape;
import java.awt.geom.Rectangle2D;
import java.util.ArrayDeque;
import java.util.Collection;
import java.util.Deque;

final class ClickboxNormalizer
{
    private static final int CELL = 4;

    private ClickboxNormalizer() {}

    /**
     * Finds a large axis-aligned rectangle whose sampled cells are all inside the real click shape.
     * This avoids treating transparent corners of an irregular polygon's bounds as clickable.
     */
    static Rectangle largestSafeRectangle(Shape shape, int canvasWidth, int canvasHeight)
    {
        if (shape == null || canvasWidth <= 0 || canvasHeight <= 0) return null;
        Rectangle clipped = shape.getBounds().intersection(new Rectangle(0, 0, canvasWidth, canvasHeight));
        if (clipped.isEmpty()) return null;

        int columns = Math.max(1, (clipped.width + CELL - 1) / CELL);
        int rows = Math.max(1, (clipped.height + CELL - 1) / CELL);
        int[] heights = new int[columns];
        Rectangle best = null;

        for (int row = 0; row < rows; row++)
        {
            int sampleY = Math.min(clipped.y + row * CELL + CELL / 2, clipped.y + clipped.height - 1);
            for (int column = 0; column < columns; column++)
            {
                int sampleX = Math.min(clipped.x + column * CELL + CELL / 2, clipped.x + clipped.width - 1);
                heights[column] = shape.contains(sampleX, sampleY) ? heights[column] + 1 : 0;
            }
            best = larger(best, largestHistogramRectangle(heights, clipped, row));
        }
        return makeContained(shape, best);
    }

    static Rectangle nearest(Rectangle pointBounds, Collection<Rectangle> candidates)
    {
        Rectangle best = null;
        double bestDistance = Double.POSITIVE_INFINITY;
        double x = pointBounds.getCenterX();
        double y = pointBounds.getCenterY();
        for (Rectangle candidate : candidates)
        {
            if (candidate == null || candidate.isEmpty()) continue;
            double dx = Math.max(candidate.x - x, Math.max(0, x - candidate.getMaxX()));
            double dy = Math.max(candidate.y - y, Math.max(0, y - candidate.getMaxY()));
            double distance = dx * dx + dy * dy;
            if (distance < bestDistance)
            {
                bestDistance = distance;
                best = candidate;
            }
        }
        return best == null ? null : new Rectangle(best);
    }

    private static Rectangle largestHistogramRectangle(int[] heights, Rectangle origin, int row)
    {
        Deque<Integer> stack = new ArrayDeque<>();
        Rectangle best = null;
        for (int index = 0; index <= heights.length; index++)
        {
            int height = index == heights.length ? 0 : heights[index];
            while (!stack.isEmpty() && heights[stack.peek()] > height)
            {
                int bar = stack.pop();
                int left = stack.isEmpty() ? 0 : stack.peek() + 1;
                int widthCells = index - left;
                Rectangle candidate = new Rectangle(origin.x + left * CELL,
                    origin.y + (row - heights[bar] + 1) * CELL,
                    Math.min(widthCells * CELL, origin.x + origin.width - (origin.x + left * CELL)),
                    Math.min(heights[bar] * CELL,
                        origin.y + origin.height - (origin.y + (row - heights[bar] + 1) * CELL)));
                best = larger(best, candidate);
            }
            stack.push(index);
        }
        return best;
    }

    private static Rectangle larger(Rectangle current, Rectangle candidate)
    {
        if (candidate == null || candidate.isEmpty()) return current;
        return current == null || area(candidate) > area(current) ? candidate : current;
    }

    private static long area(Rectangle rectangle)
    {
        return (long) rectangle.width * rectangle.height;
    }

    private static Rectangle makeContained(Shape shape, Rectangle candidate)
    {
        if (candidate == null) return null;
        Rectangle safe = new Rectangle(candidate);
        while (safe.width > 2 && safe.height > 2)
        {
            Rectangle2D interior = new Rectangle2D.Double(
                safe.x + 1, safe.y + 1, safe.width - 2, safe.height - 2);
            if (shape.contains(interior)) return safe;
            safe.grow(-CELL, -CELL);
        }
        return null;
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collection;
import java.util.List;

/** Predicts useful multi-axis experiments from layouts that were actually measured one axis at a time. */
final class CompoundViewPredictor
{
    private static final double MINIMUM_TRAVEL_IMPROVEMENT = 0.01;

    static final class Prediction
    {
        final CameraTarget target;
        final LapOptimizer.MarkerRouteScore score;

        Prediction(CameraTarget target, LapOptimizer.MarkerRouteScore score)
        {
            this.target = target;
            this.score = score;
        }
    }

    Prediction bestPrediction(SearchHistory history, CameraBounds bounds)
    {
        Prediction best = null;
        Collection<CameraCandidateStats> candidates = history.all();
        for (CameraCandidateStats base : candidates)
        {
            if (!usable(base)) continue;
            List<CameraCandidateStats> yawDonors = donors(candidates, base, Axis.YAW);
            List<CameraCandidateStats> pitchDonors = donors(candidates, base, Axis.PITCH);
            List<CameraCandidateStats> zoomDonors = donors(candidates, base, Axis.ZOOM);

            best = better(best, combinations(history, bounds, base, yawDonors, pitchDonors, null));
            best = better(best, combinations(history, bounds, base, yawDonors, null, zoomDonors));
            best = better(best, combinations(history, bounds, base, null, pitchDonors, zoomDonors));
            best = better(best, combinations(history, bounds, base, yawDonors, pitchDonors, zoomDonors));
        }
        CameraCandidateStats measuredBest = history.best();
        if (best == null || measuredBest == null || measuredBest.representativeLayout == null)
        {
            return null;
        }
        return meaningfullyBetter(best.score, score(measuredBest.representativeLayout)) ? best : null;
    }

    private Prediction combinations(SearchHistory history, CameraBounds bounds, CameraCandidateStats base,
        List<CameraCandidateStats> yawDonors, List<CameraCandidateStats> pitchDonors,
        List<CameraCandidateStats> zoomDonors)
    {
        List<CameraCandidateStats> yawChoices = choices(yawDonors);
        List<CameraCandidateStats> pitchChoices = choices(pitchDonors);
        List<CameraCandidateStats> zoomChoices = choices(zoomDonors);
        Prediction best = null;
        for (CameraCandidateStats yaw : yawChoices)
        {
            for (CameraCandidateStats pitch : pitchChoices)
            {
                for (CameraCandidateStats zoom : zoomChoices)
                {
                    int changed = count(yaw, pitch, zoom);
                    if (changed < 2) continue;
                    CameraTarget target = new CameraTarget(
                        yaw == null ? base.yaw : yaw.yaw,
                        bounds.clampPitch(pitch == null ? base.pitch : pitch.pitch),
                        bounds.clampZoom(zoom == null ? base.zoom : zoom.zoom));
                    CameraCandidateStats prior = history.get(target);
                    if (prior != null) continue;
                    ScreenMarkerLayout predicted = combine(base, yaw, pitch, zoom);
                    if (predicted == null) continue;
                    LapOptimizer.MarkerRouteScore predictedScore = score(predicted);
                    LapOptimizer.MarkerRouteScore baseScore = score(base.representativeLayout);
                    if (!meaningfullyBetter(predictedScore, baseScore)) continue;
                    best = better(best, new Prediction(target, predictedScore));
                }
            }
        }
        return best;
    }

    private static ScreenMarkerLayout combine(CameraCandidateStats base, CameraCandidateStats... donors)
    {
        ScreenMarkerLayout baseLayout = base.representativeLayout;
        int width = baseLayout.canvasWidth;
        int height = baseLayout.canvasHeight;
        List<List<Rectangle>> scaledDonors = new ArrayList<>();
        for (CameraCandidateStats donor : donors)
        {
            if (donor == null) continue;
            if (!usable(donor) || donor.representativeLayout.markers.size() != baseLayout.markers.size()) return null;
            scaledDonors.add(donor.representativeLayout.scaledTo(width, height));
        }

        List<Rectangle> markers = new ArrayList<>(baseLayout.markers.size());
        for (int i = 0; i < baseLayout.markers.size(); i++)
        {
            Rectangle original = baseLayout.markers.get(i);
            if (original == null) return null;
            int x = original.x;
            int y = original.y;
            int markerWidth = original.width;
            int markerHeight = original.height;
            for (List<Rectangle> donorLayout : scaledDonors)
            {
                Rectangle donor = donorLayout.get(i);
                if (donor == null) return null;
                x += donor.x - original.x;
                y += donor.y - original.y;
                markerWidth += donor.width - original.width;
                markerHeight += donor.height - original.height;
            }
            markerWidth = Math.max(1, Math.min(width, markerWidth));
            markerHeight = Math.max(1, Math.min(height, markerHeight));
            x = Math.max(0, Math.min(width - markerWidth, x));
            y = Math.max(0, Math.min(height - markerHeight, y));
            markers.add(new Rectangle(x, y, markerWidth, markerHeight));
        }
        return new ScreenMarkerLayout(width, height, markers);
    }

    private static List<CameraCandidateStats> donors(Collection<CameraCandidateStats> candidates,
        CameraCandidateStats base, Axis axis)
    {
        List<CameraCandidateStats> result = new ArrayList<>();
        for (CameraCandidateStats candidate : candidates)
        {
            if (!usable(candidate) || candidate == base) continue;
            boolean matches = axis == Axis.YAW
                ? candidate.pitch == base.pitch && candidate.zoom == base.zoom && candidate.yaw != base.yaw
                : axis == Axis.PITCH
                    ? candidate.yaw == base.yaw && candidate.zoom == base.zoom && candidate.pitch != base.pitch
                    : candidate.yaw == base.yaw && candidate.pitch == base.pitch && candidate.zoom != base.zoom;
            if (matches) result.add(candidate);
        }
        return result;
    }

    private static List<CameraCandidateStats> choices(List<CameraCandidateStats> donors)
    {
        List<CameraCandidateStats> result = new ArrayList<>();
        if (donors == null)
        {
            result.add(null);
            return result;
        }
        result.addAll(donors);
        return result;
    }

    private static boolean usable(CameraCandidateStats candidate)
    {
        return candidate != null && candidate.isEligible() && candidate.representativeLayout != null
            && candidate.representativeLayout.verifiedInnerRectangles
            && candidate.representativeLayout.releaseValidated
            && !candidate.representativeLayout.markers.isEmpty();
    }

    private static LapOptimizer.MarkerRouteScore score(ScreenMarkerLayout layout)
    {
        return LapOptimizer.scoreCyclicMarkers(layout.markers.toArray(new Rectangle[0]));
    }

    private static boolean meaningfullyBetter(LapOptimizer.MarkerRouteScore candidate,
        LapOptimizer.MarkerRouteScore baseline)
    {
        if (Double.isNaN(candidate.attainableTravel) || Double.isNaN(baseline.attainableTravel)) return false;
        return candidate.attainableTravel <= baseline.attainableTravel * (1 - MINIMUM_TRAVEL_IMPROVEMENT);
    }

    private static Prediction better(Prediction left, Prediction right)
    {
        if (right == null) return left;
        if (left == null) return right;
        return compare(right.score, left.score) < 0 ? right : left;
    }

    private static int compare(LapOptimizer.MarkerRouteScore left, LapOptimizer.MarkerRouteScore right)
    {
        int attainable = Double.compare(left.attainableTravel, right.attainableTravel);
        if (attainable != 0) return attainable;
        int overlap = Integer.compare(right.overlappingTransitions, left.overlappingTransitions);
        if (overlap != 0) return overlap;
        int area = Double.compare(right.overlapArea, left.overlapArea);
        if (area != 0) return area;
        return Double.compare(left.centerTravel, right.centerTravel);
    }

    private static int count(Object... values)
    {
        int count = 0;
        for (Object value : values) if (value != null) count++;
        return count;
    }

    private enum Axis { YAW, PITCH, ZOOM }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class LapOptimizer
{
    static final class CompletedLap
    {
        final double mouseTravel;
        final double markerTravel;
        final double markerGap;
        final double attainableTravel;
        final double overlapArea;
        final int overlappingTransitions;
        final int yaw;
        final int pitch;
        final int zoom;
        final boolean stableCamera;
        final List<Rectangle> markers;

        CompletedLap(double mouseTravel, MarkerRouteScore markerScore, int yaw, int pitch, int zoom,
            boolean stableCamera, List<Rectangle> markers)
        {
            this.mouseTravel = mouseTravel;
            this.markerTravel = markerScore.centerTravel;
            this.markerGap = markerScore.gapTravel;
            this.attainableTravel = markerScore.attainableTravel;
            this.overlapArea = markerScore.overlapArea;
            this.overlappingTransitions = markerScore.overlappingTransitions;
            this.yaw = yaw;
            this.pitch = pitch;
            this.zoom = zoom;
            this.stableCamera = stableCamera;
            this.markers = markers;
        }
    }

    private int routeSize;
    private boolean active;
    private int expectedIndex;
    private int lastObstacleIndex = -1;
    private boolean hasMouseSample;
    private int lastMouseX;
    private int lastMouseY;
    private double currentTravel;
    private double lastTravel = Double.NaN;
    private double lastMarkerTravel = Double.NaN;
    private double lastMarkerGap = Double.NaN;
    private int lastOverlappingTransitions;
    private boolean lastLapStable;
    private int startYaw;
    private int startPitch;
    private int startZoom;
    private boolean cameraAlignedAtCheckpoints;
    private int completedLaps;
    private Rectangle[] markers = new Rectangle[0];

    void reset(int routeSize)
    {
        this.routeSize = routeSize;
        active = false;
        expectedIndex = 0;
        lastObstacleIndex = -1;
        hasMouseSample = false;
        currentTravel = 0;
        lastTravel = Double.NaN;
        lastMarkerTravel = Double.NaN;
        lastMarkerGap = Double.NaN;
        lastOverlappingTransitions = 0;
        lastLapStable = false;
        completedLaps = 0;
        markers = new Rectangle[Math.max(0, routeSize)];
    }

    void sampleMouse(int x, int y, int yaw, int pitch, int zoom)
    {
        if (!active)
        {
            return;
        }
        if (hasMouseSample)
        {
            currentTravel += Math.hypot(x - lastMouseX, y - lastMouseY);
        }
        lastMouseX = x;
        lastMouseY = y;
        hasMouseSample = true;
    }

    void pauseMouseSampling() { hasMouseSample = false; }
    void cameraAdjusted() { if (active) pauseMouseSampling(); }
    void cameraTargetRejected()
    {
        if (active)
        {
            cameraAlignedAtCheckpoints = false;
            active = false;
            hasMouseSample = false;
        }
    }

    CompletedLap obstacleClicked(int index, int mouseX, int mouseY, int yaw, int pitch, int zoom,
        Rectangle clickbox)
    {
        return obstacleClicked(index, mouseX, mouseY, yaw, pitch, zoom, clickbox, true);
    }

    CompletedLap obstacleClicked(int index, int mouseX, int mouseY, int yaw, int pitch, int zoom,
        Rectangle clickbox, boolean cameraAligned)
    {
        if (index == 0)
        {
            if (active && routeSize == 1)
            {
                sampleMouse(mouseX, mouseY, yaw, pitch, zoom);
                CompletedLap completed = finishLap();
                beginLap(mouseX, mouseY, yaw, pitch, zoom, clickbox, cameraAligned);
                return completed;
            }
            beginLap(mouseX, mouseY, yaw, pitch, zoom, clickbox, cameraAligned);
            return null;
        }
        if (!active || index == lastObstacleIndex)
        {
            return null;
        }
        if (index != expectedIndex)
        {
            active = false;
            hasMouseSample = false;
            return null;
        }
        sampleMouse(mouseX, mouseY, yaw, pitch, zoom);
        cameraAlignedAtCheckpoints &= cameraAligned;
        markers[index] = copy(clickbox);
        lastObstacleIndex = index;
        expectedIndex++;
        return expectedIndex == routeSize ? finishLap() : null;
    }

    boolean isActive() { return active; }
    int getProgress() { return active ? Math.min(expectedIndex, routeSize) : 0; }
    double getCurrentTravel() { return currentTravel; }
    double getLastTravel() { return lastTravel; }
    double getLastMarkerTravel() { return lastMarkerTravel; }
    double getLastMarkerGap() { return lastMarkerGap; }
    int getLastOverlappingTransitions() { return lastOverlappingTransitions; }
    boolean wasLastLapStable() { return lastLapStable; }
    boolean isCurrentLapStableSoFar()
    {
        return !active || cameraAlignedAtCheckpoints;
    }
    int getCompletedLaps() { return completedLaps; }

    private void beginLap(int mouseX, int mouseY, int yaw, int pitch, int zoom, Rectangle clickbox,
        boolean cameraAligned)
    {
        active = routeSize > 0;
        expectedIndex = routeSize == 1 ? routeSize : 1;
        lastObstacleIndex = 0;
        currentTravel = 0;
        hasMouseSample = true;
        lastMouseX = mouseX;
        lastMouseY = mouseY;
        startYaw = yaw;
        startPitch = pitch;
        startZoom = zoom;
        cameraAlignedAtCheckpoints = cameraAligned;
        markers = new Rectangle[Math.max(0, routeSize)];
        if (routeSize > 0)
        {
            markers[0] = copy(clickbox);
        }
    }

    private CompletedLap finishLap()
    {
        active = false;
        hasMouseSample = false;
        lastTravel = currentTravel;
        MarkerRouteScore markerScore = scoreCyclicMarkers(markers);
        lastMarkerTravel = markerScore.centerTravel;
        lastMarkerGap = markerScore.gapTravel;
        lastOverlappingTransitions = markerScore.overlappingTransitions;
        lastLapStable = cameraAlignedAtCheckpoints;
        completedLaps++;
        List<Rectangle> snapshot = new ArrayList<>(markers.length);
        for (Rectangle marker : markers)
        {
            snapshot.add(copy(marker));
        }
        return new CompletedLap(lastTravel, markerScore, startYaw, startPitch, startZoom,
            lastLapStable, Collections.unmodifiableList(snapshot));
    }

    static final class MarkerRouteScore
    {
        final double centerTravel;
        final double gapTravel;
        final double attainableTravel;
        final double overlapArea;
        final int overlappingTransitions;

        MarkerRouteScore(double centerTravel, double gapTravel, double attainableTravel, double overlapArea,
            int overlappingTransitions)
        {
            this.centerTravel = centerTravel;
            this.gapTravel = gapTravel;
            this.attainableTravel = attainableTravel;
            this.overlapArea = overlapArea;
            this.overlappingTransitions = overlappingTransitions;
        }
    }

    static MarkerRouteScore scoreCyclicMarkers(Rectangle[] markers)
    {
        if (markers == null || markers.length == 0)
        {
            return new MarkerRouteScore(Double.NaN, Double.NaN, Double.NaN, Double.NaN, 0);
        }
        double centerTotal = 0;
        double gapTotal = 0;
        double overlapArea = 0;
        int overlaps = 0;
        for (int i = 0; i < markers.length; i++)
        {
            Rectangle from = markers[i];
            Rectangle to = markers[(i + 1) % markers.length];
            if (from == null || to == null)
            {
                return new MarkerRouteScore(Double.NaN, Double.NaN, Double.NaN, Double.NaN, 0);
            }
            centerTotal += Math.hypot(to.getCenterX() - from.getCenterX(), to.getCenterY() - from.getCenterY());
            double dx = Math.max(0, Math.max(from.x - (to.x + to.width), to.x - (from.x + from.width)));
            double dy = Math.max(0, Math.max(from.y - (to.y + to.height), to.y - (from.y + from.height)));
            gapTotal += Math.hypot(dx, dy);
            Rectangle intersection = from.intersection(to);
            if (!intersection.isEmpty())
            {
                overlaps++;
                overlapArea += (double) intersection.width * intersection.height;
            }
        }
        double attainable = AttainableRouteOptimizer.solve(markers).travel;
        return new MarkerRouteScore(centerTotal, gapTotal, attainable, overlapArea, overlaps);
    }

    private static Rectangle copy(Rectangle rectangle)
    {
        return rectangle == null ? null : new Rectangle(rectangle);
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.List;

final class LayoutScorer
{
    private LayoutScorer() {}

    static double score(List<Rectangle> orderedClickboxes, int viewportWidth, int viewportHeight)
    {
        if (orderedClickboxes.isEmpty() || viewportWidth <= 0 || viewportHeight <= 0)
        {
            return 0;
        }

        double diagonal = Math.hypot(viewportWidth, viewportHeight);
        double travel = 0;
        double targetUsability = 0;
        for (int i = 0; i < orderedClickboxes.size(); i++)
        {
            Rectangle box = orderedClickboxes.get(i);
            double area = Math.max(0, box.width * box.height);
            targetUsability += Math.min(250.0, area / 40.0);
            if (i > 0)
            {
                Rectangle previous = orderedClickboxes.get(i - 1);
                travel += Math.hypot(box.getCenterX() - previous.getCenterX(),
                    box.getCenterY() - previous.getCenterY()) / diagonal;
            }
        }

        double visibility = orderedClickboxes.size() * 1_000.0;
        return visibility + targetUsability - travel * 120.0;
    }
}

