import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

final class RooftopGhostOverlay extends Overlay
{
    private final RooftopCameraPlugin plugin;

    @Inject
    RooftopGhostOverlay(RooftopCameraPlugin plugin)
    {
        this.plugin = plugin;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_WIDGETS);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        List<Rectangle> markers = plugin.getScaledBestMarkers();
        int next = plugin.getNextObstacleNumber() - 1;
        for (int i = 0; i < markers.size(); i++)
        {
            Rectangle marker = markers.get(i);
            if (marker == null) continue;
            boolean isNext = i == next;
            graphics.setColor(isNext ? new Color(67, 232, 201, 65) : new Color(255, 196, 64, 35));
            graphics.fill(marker);
            graphics.setColor(isNext ? new Color(67, 232, 201, 225) : new Color(255, 196, 64, 175));
            graphics.setStroke(new BasicStroke(isNext ? 3f : 1.5f));
            graphics.draw(marker);
            graphics.drawString(Integer.toString(i + 1), marker.x + 4, marker.y + 14);
        }
        return null;
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.awt.Shape;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.TileObject;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;

final class RooftopSceneOverlay extends Overlay
{
    private final RooftopCameraPlugin plugin;
    private final RooftopCameraConfig config;

    @Inject
    RooftopSceneOverlay(RooftopCameraPlugin plugin, RooftopCameraConfig config)
    {
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.DYNAMIC);
        setLayer(OverlayLayer.ABOVE_SCENE);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        int nextStep = plugin.getNextObstacleNumber() - 1;
        for (Map.Entry<TileObject, Integer> entry : plugin.getTracked().entrySet())
        {
            TileObject object = entry.getKey();
            boolean isNext = entry.getValue() == nextStep;
            if (!isNext && !config.showAllObstacles())
            {
                continue;
            }
            Shape clickbox = object.getClickbox();
            if (clickbox == null)
            {
                continue;
            }
            Color color = isNext ? config.nextColor() : config.obstacleColor();
            graphics.setStroke(new BasicStroke(isNext ? 3f : 1.5f));
            OverlayUtil.renderPolygon(graphics, clickbox, color);
            java.awt.Rectangle bounds = clickbox.getBounds();
            OverlayUtil.renderTextLocation(graphics,
                new net.runelite.api.Point((int) bounds.getCenterX(), (int) bounds.getCenterY()),
                Integer.toString(entry.getValue() + 1), color);
        }
        drawScreenMarkers(graphics, plugin.getScaledBestMarkers(), plugin.getNextObstacleNumber() - 1);
        return null;
    }

    private static void drawScreenMarkers(Graphics2D graphics, List<Rectangle> markers, int next)
    {
        for (int i = 0; i < markers.size(); i++)
        {
            Rectangle marker = markers.get(i);
            if (marker == null) continue;

            boolean isNext = i == next;
            Color edge = isNext ? new Color(42, 255, 220) : new Color(255, 196, 64);
            Color fill = isNext ? new Color(42, 255, 220, 115) : new Color(255, 196, 64, 90);

            graphics.setColor(new Color(0, 0, 0, 220));
            graphics.setStroke(new BasicStroke(isNext ? 6f : 5f));
            graphics.draw(marker);
            graphics.setColor(fill);
            graphics.fill(marker);
            graphics.setColor(edge);
            graphics.setStroke(new BasicStroke(isNext ? 3f : 2f));
            graphics.draw(marker);

            String label = "M" + (i + 1);
            int labelX = marker.x + Math.max(3, marker.width / 2 - graphics.getFontMetrics().stringWidth(label) / 2);
            int labelY = marker.y + Math.max(13, marker.height / 2 + 5);
            graphics.setColor(new Color(0, 0, 0, 235));
            graphics.drawString(label, labelX + 1, labelY + 1);
            graphics.setColor(edge);
            graphics.drawString(label, labelX, labelY);
        }
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;

final class ScreenMarkerAligner
{
    private static final int MIN_MATCHES = 2;
    private static final int MAX_CORRECTION = 160;

    private ScreenMarkerAligner() {}

    static List<Rectangle> align(List<Rectangle> saved, Map<Integer, Rectangle> live,
        int canvasWidth, int canvasHeight)
    {
        List<Integer> deltaX = new ArrayList<>();
        List<Integer> deltaY = new ArrayList<>();
        for (Map.Entry<Integer, Rectangle> entry : live.entrySet())
        {
            int index = entry.getKey();
            if (index < 0 || index >= saved.size()) continue;
            Rectangle before = saved.get(index);
            Rectangle now = entry.getValue();
            if (before == null || now == null) continue;
            deltaX.add((int) Math.round(now.getCenterX() - before.getCenterX()));
            deltaY.add((int) Math.round(now.getCenterY() - before.getCenterY()));
        }

        int dx = deltaX.size() >= MIN_MATCHES ? clamp(median(deltaX), -MAX_CORRECTION, MAX_CORRECTION) : 0;
        int dy = deltaY.size() >= MIN_MATCHES ? clamp(median(deltaY), -MAX_CORRECTION, MAX_CORRECTION) : 0;
        int markerCount = saved.size();
        for (Integer index : live.keySet())
        {
            if (index != null && index >= 0) markerCount = Math.max(markerCount, index + 1);
        }

        List<Rectangle> adjusted = new ArrayList<>(markerCount);
        for (int index = 0; index < markerCount; index++)
        {
            Rectangle liveMarker = live.get(index);
            if (liveMarker != null)
            {
                adjusted.add(clampToCanvas(liveMarker, canvasWidth, canvasHeight));
                continue;
            }

            Rectangle marker = index < saved.size() ? saved.get(index) : null;
            if (marker == null)
            {
                adjusted.add(null);
                continue;
            }
            int x = clamp(marker.x + dx, 0, Math.max(0, canvasWidth - marker.width));
            int y = clamp(marker.y + dy, 0, Math.max(0, canvasHeight - marker.height));
            adjusted.add(new Rectangle(x, y, marker.width, marker.height));
        }
        return adjusted;
    }

    private static Rectangle clampToCanvas(Rectangle marker, int canvasWidth, int canvasHeight)
    {
        int width = Math.max(1, Math.min(marker.width, Math.max(1, canvasWidth)));
        int height = Math.max(1, Math.min(marker.height, Math.max(1, canvasHeight)));
        int x = clamp(marker.x, 0, Math.max(0, canvasWidth - width));
        int y = clamp(marker.y, 0, Math.max(0, canvasHeight - height));
        return new Rectangle(x, y, width, height);
    }

    private static int median(List<Integer> values)
    {
        Collections.sort(values);
        int middle = values.size() / 2;
        return values.size() % 2 == 1 ? values.get(middle)
            : (int) Math.round((values.get(middle - 1) + values.get(middle)) / 2d);
    }

    private static int clamp(int value, int minimum, int maximum)
    {
        return Math.max(minimum, Math.min(maximum, value));
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

final class ScreenMarkerLayout
{
    final int canvasWidth;
    final int canvasHeight;
    final List<Rectangle> markers;
    final boolean verifiedInnerRectangles;
    /** Captured by the current release's live-lap verifier. */
    final boolean releaseValidated;

    ScreenMarkerLayout(int canvasWidth, int canvasHeight, List<Rectangle> markers)
    {
        this(canvasWidth, canvasHeight, markers, true, true);
    }

    private ScreenMarkerLayout(int canvasWidth, int canvasHeight, List<Rectangle> markers,
        boolean verifiedInnerRectangles, boolean releaseValidated)
    {
        this.canvasWidth = canvasWidth;
        this.canvasHeight = canvasHeight;
        this.verifiedInnerRectangles = verifiedInnerRectangles;
        this.releaseValidated = releaseValidated;
        List<Rectangle> copy = new ArrayList<>(markers.size());
        for (Rectangle marker : markers)
        {
            copy.add(marker == null ? null : new Rectangle(marker));
        }
        this.markers = Collections.unmodifiableList(copy);
    }

    List<Rectangle> scaledTo(int width, int height)
    {
        if (canvasWidth <= 0 || canvasHeight <= 0 || width <= 0 || height <= 0)
        {
            return Collections.emptyList();
        }
        double scaleX = (double) width / canvasWidth;
        double scaleY = (double) height / canvasHeight;
        List<Rectangle> scaled = new ArrayList<>(markers.size());
        for (Rectangle marker : markers)
        {
            scaled.add(marker == null ? null : new Rectangle(
                (int) Math.round(marker.x * scaleX), (int) Math.round(marker.y * scaleY),
                Math.max(1, (int) Math.round(marker.width * scaleX)),
                Math.max(1, (int) Math.round(marker.height * scaleY))));
        }
        return scaled;
    }

    String serialize()
    {
        StringBuilder result = new StringBuilder("v3|" + canvasWidth + "," + canvasHeight + "|");
        for (int i = 0; i < markers.size(); i++)
        {
            if (i > 0) result.append(';');
            Rectangle marker = markers.get(i);
            if (marker != null)
            {
                result.append(marker.x).append(':').append(marker.y).append(':')
                    .append(marker.width).append(':').append(marker.height);
            }
        }
        return result.toString();
    }

    static ScreenMarkerLayout parse(String value)
    {
        if (value == null || value.isEmpty()) return null;
        try
        {
            String[] sections = value.split("\\|", -1);
            boolean v3 = sections.length == 3 && "v3".equals(sections[0]);
            boolean v2 = sections.length == 3 && "v2".equals(sections[0]);
            boolean verified = v2 || v3;
            if (!verified && sections.length != 2) return null;
            String[] size = sections[verified ? 1 : 0].split(",");
            if (size.length != 2) return null;
            List<Rectangle> markers = new ArrayList<>();
            String encodedMarkers = sections[verified ? 2 : 1];
            if (!encodedMarkers.isEmpty())
            {
                for (String encoded : encodedMarkers.split(";", -1))
                {
                    if (encoded.isEmpty())
                    {
                        markers.add(null);
                        continue;
                    }
                    String[] fields = encoded.split(":");
                    if (fields.length != 4) return null;
                    markers.add(new Rectangle(Integer.parseInt(fields[0]), Integer.parseInt(fields[1]),
                        Integer.parseInt(fields[2]), Integer.parseInt(fields[3])));
                }
            }
            // v2 layouts remain available as historical search evidence, but they
            // cannot be rendered until a current live lap verifies their geometry.
            return new ScreenMarkerLayout(Integer.parseInt(size[0]), Integer.parseInt(size[1]), markers,
                verified, v3);
        }
        catch (NumberFormatException ignored)
        {
            return null;
        }
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Base64;
import java.util.Collection;
import java.util.LinkedHashMap;
import java.util.Map;

final class SearchHistory
{
    private final Map<String, CameraCandidateStats> candidates = new LinkedHashMap<>();

    CameraCandidateStats get(CameraTarget target) { return candidates.get(target.key()); }

    CameraCandidateStats getOrCreate(int yaw, int pitch, int zoom)
    {
        CameraTarget target = new CameraTarget(yaw, pitch, zoom);
        return candidates.computeIfAbsent(target.key(), ignored -> new CameraCandidateStats(yaw, pitch, zoom));
    }

    Collection<CameraCandidateStats> all() { return candidates.values(); }

    CameraCandidateStats first()
    {
        for (CameraCandidateStats candidate : candidates.values()) return candidate;
        return null;
    }

    CameraCandidateStats firstEligible()
    {
        for (CameraCandidateStats candidate : candidates.values())
        {
            if (candidate.isEligible()) return candidate;
        }
        return null;
    }

    CameraCandidateStats best()
    {
        CameraCandidateStats best = null;
        for (CameraCandidateStats candidate : candidates.values())
        {
            if (candidate.isEligible() && candidate.isBetterThan(best)) best = candidate;
        }
        return best;
    }

    CameraCandidateStats bestOperational()
    {
        CameraCandidateStats best = null;
        for (CameraCandidateStats candidate : candidates.values())
        {
            if (candidate.isEligible() && candidate.isOperational() && candidate.isBetterThan(best))
            {
                best = candidate;
            }
        }
        return best;
    }

    int testedCount()
    {
        int count = 0;
        for (CameraCandidateStats candidate : candidates.values()) if (candidate.isEligible()) count++;
        return count;
    }

    int totalSamples()
    {
        int count = 0;
        for (CameraCandidateStats candidate : candidates.values()) count += candidate.samples;
        return count;
    }

    String serialize()
    {
        ArrayList<String> entries = new ArrayList<>();
        for (CameraCandidateStats c : candidates.values())
        {
            String layout = c.representativeLayout == null ? "" : Base64.getUrlEncoder().withoutPadding()
                .encodeToString(c.representativeLayout.serialize().getBytes(StandardCharsets.UTF_8));
            entries.add(c.yaw + "," + c.pitch + "," + c.zoom + "," + c.samples + ","
                + c.overlapTotal + "," + c.overlapAreaTotal + "," + c.gapTotal + ","
                + c.centerTotal + "," + c.mouseTotal + "," + layout + "," + c.rejections);
        }
        return String.join("~", entries);
    }

    static SearchHistory parse(String value)
    {
        SearchHistory history = new SearchHistory();
        if (value == null || value.isEmpty()) return history;
        try
        {
            for (String entry : value.split("~"))
            {
                String[] f = entry.split(",", -1);
                if (f.length != 9 && f.length != 10 && f.length != 11) continue;
                CameraCandidateStats c = history.getOrCreate(Integer.parseInt(f[0]), Integer.parseInt(f[1]), Integer.parseInt(f[2]));
                c.samples = Integer.parseInt(f[3]);
                c.overlapTotal = Double.parseDouble(f[4]);
                int offset = f.length >= 10 ? 1 : 0;
                c.overlapAreaTotal = offset == 1 ? Double.parseDouble(f[5]) : 0;
                c.gapTotal = Double.parseDouble(f[5 + offset]);
                c.centerTotal = Double.parseDouble(f[6 + offset]);
                c.mouseTotal = Double.parseDouble(f[7 + offset]);
                if (!f[8 + offset].isEmpty())
                {
                    String decoded = new String(Base64.getUrlDecoder().decode(f[8 + offset]), StandardCharsets.UTF_8);
                    c.representativeLayout = ScreenMarkerLayout.parse(decoded);
                }
                if (f.length == 11)
                {
                    c.rejections = Integer.parseInt(f[10]);
                }
            }
        }
        catch (IllegalArgumentException ignored)
        {
            return new SearchHistory();
        }
        return history;
    }
}

package com.mvpitsolutions.rooftopcamera;

final class TravelProfile
{
    final int yaw;
    final int pitch;
    final int zoom;
    final double markerTravel;
    final double markerGap;
    final double overlappingTransitions;
    final double overlapArea;
    final double observedMouseTravel;
    final int samples;

    TravelProfile(int yaw, int pitch, int zoom, double markerTravel, double markerGap,
        double overlappingTransitions, double overlapArea, double observedMouseTravel, int samples)
    {
        this.yaw = yaw;
        this.pitch = pitch;
        this.zoom = zoom;
        this.markerTravel = markerTravel;
        this.markerGap = markerGap;
        this.overlappingTransitions = overlappingTransitions;
        this.overlapArea = overlapArea;
        this.observedMouseTravel = observedMouseTravel;
        this.samples = samples;
    }

    String serialize()
    {
        return yaw + "," + pitch + "," + zoom + "," + markerTravel + "," + markerGap + ","
            + overlappingTransitions + "," + overlapArea + "," + observedMouseTravel + "," + samples;
    }

    static TravelProfile parse(String value)
    {
        if (value == null || value.isEmpty())
        {
            return null;
        }
        try
        {
            String[] fields = value.split(",");
            if (fields.length != 8 && fields.length != 9)
            {
                return null;
            }
            int offset = fields.length == 9 ? 1 : 0;
            return new TravelProfile(Integer.parseInt(fields[0]), Integer.parseInt(fields[1]),
                Integer.parseInt(fields[2]), Double.parseDouble(fields[3]), Double.parseDouble(fields[4]),
                Double.parseDouble(fields[5]), offset == 1 ? Double.parseDouble(fields[6]) : 0,
                Double.parseDouble(fields[6 + offset]), Integer.parseInt(fields[7 + offset]));
        }
        catch (NumberFormatException ignored)
        {
            return null;
        }
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.awt.geom.Point2D;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

public class AttainableRouteOptimizerTest
{
    @Test
    public void choosesOneLegalPointPerMarkerDeterministically()
    {
        Rectangle[] markers = {
            new Rectangle(0, 0, 20, 20), new Rectangle(80, 0, 20, 20),
            new Rectangle(80, 80, 20, 20), new Rectangle(0, 80, 20, 20)
        };
        AttainableRouteOptimizer.Result first = AttainableRouteOptimizer.solve(markers);
        AttainableRouteOptimizer.Result second = AttainableRouteOptimizer.solve(markers);

        assertEquals(first.travel, second.travel, 0.0001);
        assertEquals(markers.length, first.points.size());
        for (int i = 0; i < markers.length; i++)
        {
            Point2D point = first.points.get(i);
            assertTrue(markers[i].contains(point) || onInclusiveEdge(markers[i], point));
        }
    }

    @Test
    public void attainableRouteStaysBetweenIndependentGapBoundAndCenterRoute()
    {
        Rectangle[] markers = {
            new Rectangle(0, 0, 1, 1),
            new Rectangle(0, 0, 101, 1),
            new Rectangle(100, 0, 1, 1)
        };
        LapOptimizer.MarkerRouteScore score = LapOptimizer.scoreCyclicMarkers(markers);

        assertTrue(score.attainableTravel > score.gapTravel * 1.5);
        assertTrue(score.attainableTravel <= score.centerTravel + 0.01);
    }

    @Test
    public void overlappingMarkersCanProduceZeroTravel()
    {
        Rectangle[] markers = {
            new Rectangle(10, 10, 50, 50), new Rectangle(20, 20, 20, 20),
            new Rectangle(15, 15, 30, 30)
        };
        assertEquals(0, AttainableRouteOptimizer.solve(markers).travel, 0.01);
    }

    private static boolean onInclusiveEdge(Rectangle rectangle, Point2D point)
    {
        return point.getX() >= rectangle.getMinX() && point.getX() <= rectangle.getMaxX()
            && point.getY() >= rectangle.getMinY() && point.getY() <= rectangle.getMaxY();
    }
}

