public class ScreenMarkerAlignerTest
{
    @Test
    public void appliesMedianCorrectionFromMultipleLiveObstacles()
    {
        List<Rectangle> saved = Arrays.asList(new Rectangle(10, 10, 20, 20),
            new Rectangle(50, 50, 20, 20), new Rectangle(90, 90, 20, 20));
        Map<Integer, Rectangle> live = new HashMap<>();
        live.put(0, new Rectangle(16, 6, 20, 20));
        live.put(1, new Rectangle(54, 44, 20, 20));
        live.put(2, new Rectangle(96, 86, 20, 20));

        List<Rectangle> adjusted = ScreenMarkerAligner.align(saved, live, 200, 200);

        assertEquals(new Rectangle(16, 6, 20, 20), adjusted.get(0));
        assertEquals(new Rectangle(54, 44, 20, 20), adjusted.get(1));
        assertEquals(new Rectangle(96, 86, 20, 20), adjusted.get(2));
    }

    @Test
    public void ignoresSingleMatchAndClampsToCanvas()
    {
        List<Rectangle> saved = Arrays.asList(new Rectangle(95, 95, 10, 10),
            new Rectangle(10, 10, 10, 10));
        Map<Integer, Rectangle> live = new HashMap<>();
        live.put(0, new Rectangle(500, 500, 10, 10));

        List<Rectangle> adjusted = ScreenMarkerAligner.align(saved, live, 100, 100);

        assertEquals(new Rectangle(90, 90, 10, 10), adjusted.get(0));
        assertEquals(new Rectangle(10, 10, 10, 10), adjusted.get(1));
    }

    @Test
    public void liveProjectionCanRestoreAMissingSavedRouteStep()
    {
        List<Rectangle> saved = Arrays.asList(new Rectangle(10, 10, 20, 20), null);
        Map<Integer, Rectangle> live = new HashMap<>();
        live.put(1, new Rectangle(70, 80, 15, 18));

        List<Rectangle> adjusted = ScreenMarkerAligner.align(saved, live, 200, 200);

        assertEquals(new Rectangle(10, 10, 20, 20), adjusted.get(0));
        assertEquals(new Rectangle(70, 80, 15, 18), adjusted.get(1));
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class ScreenMarkerLayoutTest
{
    @Test
    public void calibratedLayoutScalingIsStableAcrossRepeatedFrames()
    {
        ScreenMarkerLayout layout = new ScreenMarkerLayout(100, 100, Arrays.asList(
            new Rectangle(10, 20, 30, 40),
            new Rectangle(55, 60, 20, 15)));

        List<Rectangle> firstFrame = layout.scaledTo(200, 200);
        List<Rectangle> laterFrame = layout.scaledTo(200, 200);

        assertEquals(firstFrame, laterFrame);
        assertEquals(new Rectangle(20, 40, 60, 80), laterFrame.get(0));
        assertEquals(new Rectangle(110, 120, 40, 30), laterFrame.get(1));
    }

    @Test
    public void roundTripsAndScalesMarkers()
    {
        ScreenMarkerLayout original = new ScreenMarkerLayout(800, 600,
            Arrays.asList(new Rectangle(100, 120, 40, 20), null, new Rectangle(600, 300, 80, 40)));
        ScreenMarkerLayout parsed = ScreenMarkerLayout.parse(original.serialize());
        org.junit.Assert.assertTrue(parsed.verifiedInnerRectangles);
        org.junit.Assert.assertTrue(parsed.releaseValidated);
        List<Rectangle> scaled = parsed.scaledTo(1600, 1200);
        assertEquals(new Rectangle(200, 240, 80, 40), scaled.get(0));
        assertNull(scaled.get(1));
        assertEquals(new Rectangle(1200, 600, 160, 80), scaled.get(2));
    }

    @Test
    public void legacyBoundingBoxesRemainReadableButUnverified()
    {
        ScreenMarkerLayout parsed = ScreenMarkerLayout.parse("800,600|1:2:3:4");
        org.junit.Assert.assertFalse(parsed.verifiedInnerRectangles);
        assertEquals(new Rectangle(1, 2, 3, 4), parsed.markers.get(0));
    }

    @Test
    public void v2LayoutsRemainReadableButCannotBeUsedAsReleaseMarkers()
    {
        ScreenMarkerLayout parsed = ScreenMarkerLayout.parse("v2|800,600|1:2:30:40");

        org.junit.Assert.assertTrue(parsed.verifiedInnerRectangles);
        org.junit.Assert.assertFalse(parsed.releaseValidated);
        assertEquals(new Rectangle(1, 2, 30, 40), parsed.markers.get(0));
    }

    @Test
    public void liveObstacleClickboxCorrectsAStaleCalibratedMarker()
    {
        List<Rectangle> saved = Arrays.asList(
            new Rectangle(10, 10, 20, 20), new Rectangle(40, 40, 20, 20));
        Rectangle live = new Rectangle(14, 18, 28, 24);

        List<Rectangle> merged = RooftopCameraPlugin.mergeLiveMarkers(saved,
            Collections.singletonMap(0, live));

        assertEquals(live, merged.get(0));
        assertEquals(saved.get(1), merged.get(1));
        assertEquals(new Rectangle(10, 10, 20, 20), saved.get(0));
    }

    @Test
    public void liveClickboxFillsOnlyAMissingCalibratedMarker()
    {
        Rectangle live = new Rectangle(14, 18, 28, 24);
        List<Rectangle> merged = RooftopCameraPlugin.mergeLiveMarkers(
            Arrays.asList(null, new Rectangle(40, 40, 20, 20)), Collections.singletonMap(0, live));

        assertEquals(live, merged.get(0));
        assertEquals(new Rectangle(40, 40, 20, 20), merged.get(1));
    }
}

package com.mvpitsolutions.rooftopcamera;

import java.awt.Rectangle;
import java.util.Arrays;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;

public class SearchHistoryTest
{
    @Test
    public void persistsCandidateEvidenceAndMarkerLayout()
    {
        SearchHistory history = new SearchHistory();
        CameraCandidateStats candidate = history.getOrCreate(32, 1200, 512);
        candidate.samples = 3;
        candidate.overlapTotal = 9;
        candidate.overlapAreaTotal = 270;
        candidate.gapTotal = 300;
        candidate.centerTotal = 600;
        candidate.mouseTotal = 900;
        candidate.rejections = 1;
        candidate.representativeLayout = new ScreenMarkerLayout(800, 600,
            Arrays.asList(new Rectangle(1, 2, 3, 4), new Rectangle(5, 6, 7, 8)));

        SearchHistory parsed = SearchHistory.parse(history.serialize());
        CameraCandidateStats restored = parsed.get(new CameraTarget(32, 1200, 512));
        assertNotNull(restored);
        assertEquals(3, restored.samples);
        assertEquals(3.0, restored.averageOverlap(), 0.001);
        assertEquals(90.0, restored.averageOverlapArea(), 0.001);
        assertEquals(1, restored.rejections);
        assertEquals(new Rectangle(1, 2, 3, 4), restored.representativeLayout.markers.get(0));
    }

    @Test
    public void reranksWhenIncumbentAverageDegrades()
    {
        SearchHistory history = new SearchHistory();
        CameraCandidateStats first = history.getOrCreate(0, 1000, 500);
        first.samples = 2; first.overlapTotal = 6; first.gapTotal = 200; first.centerTotal = 500; first.mouseTotal = 700;
        CameraCandidateStats second = history.getOrCreate(16, 1000, 500);
        second.samples = 2; second.overlapTotal = 4; second.gapTotal = 100; second.centerTotal = 400; second.mouseTotal = 600;
        assertEquals(first, history.best());
        first.samples = 4; first.overlapTotal = 6;
        assertEquals(second, history.best());
    }

    @Test
    public void overlapAreaBreaksTiesBeforeTravel()
    {
        SearchHistory history = new SearchHistory();
        CameraCandidateStats narrow = history.getOrCreate(0, 1000, 500);
        narrow.samples = 2; narrow.overlapTotal = 4; narrow.overlapAreaTotal = 100;
        narrow.gapTotal = 0; narrow.centerTotal = 100; narrow.mouseTotal = 100;
        CameraCandidateStats broad = history.getOrCreate(16, 1000, 500);
        broad.samples = 2; broad.overlapTotal = 4; broad.overlapAreaTotal = 200;
        broad.gapTotal = 0; broad.centerTotal = 1000; broad.mouseTotal = 1000;
        assertEquals(broad, history.best());
    }

    @Test
    public void measuredOverlapOutranksSpeculativeDistance()
    {
        SearchHistory history = new SearchHistory();
        CameraCandidateStats compact = history.getOrCreate(0, 1000, 500);
        compact.samples = 1;
        compact.representativeLayout = new ScreenMarkerLayout(500, 500, Arrays.asList(
            new Rectangle(0, 0, 10, 10), new Rectangle(50, 0, 10, 10),
            new Rectangle(50, 50, 10, 10), new Rectangle(0, 50, 10, 10)));
        CameraCandidateStats misleadingOverlap = history.getOrCreate(16, 1000, 500);
        misleadingOverlap.samples = 1;
        misleadingOverlap.overlapTotal = 1;
        misleadingOverlap.representativeLayout = new ScreenMarkerLayout(500, 500, Arrays.asList(
            new Rectangle(0, 0, 100, 10), new Rectangle(90, 0, 10, 10),
            new Rectangle(400, 400, 10, 10), new Rectangle(0, 400, 10, 10)));

        assertEquals(misleadingOverlap, history.best());
    }

    @Test
    public void operationalWinnerRejectsAnEffectivelyInvisibleStep()
    {
        SearchHistory history = new SearchHistory();
        CameraCandidateStats unsafe = history.getOrCreate(0, 1000, 500);
        unsafe.samples = 1;
        unsafe.gapTotal = 1;
        unsafe.representativeLayout = new ScreenMarkerLayout(500, 500, Arrays.asList(
            new Rectangle(0, 0, 20, 20), new Rectangle(50, 0, 40, 4)));
        CameraCandidateStats safe = history.getOrCreate(16, 1000, 500);
        safe.samples = 1;
        safe.gapTotal = 100;
        safe.representativeLayout = new ScreenMarkerLayout(500, 500, Arrays.asList(
            new Rectangle(0, 0, 20, 20), new Rectangle(50, 0, 20, 12)));

        assertEquals(safe, history.bestOperational());
    }

    @Test
    public void historicalLayoutsCannotWinOperationalSelectionUntilRelived()
    {
        SearchHistory history = SearchHistory.parse("32,1200,512,2,4,0,100,200,300,"
            + "djJ8ODAwLDYwMHwxOjI6MjA6MjA,0");

        assertNull(history.bestOperational());
    }
}
